const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL files from the migrations directory and logs each filename in order.
 * Migration files are sorted alphabetically by filename.
 */
function getMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files in order (alphabetically by filename)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function that logs which migrations would be applied
 */
function migrate() {
  console.log('Starting migration process...\n');

  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s):\n`);

  // Log each filename that would be applied, in order
  migrations.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\nMigration complete.');
}

// Run the migration
migrate();

