const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Reads SQL files from the migrations directory and logs each filename
 * that would be applied, in order.
 */
function migrate() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory does not exist:', MIGRATIONS_DIR);
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files in order (by filename, so use numeric prefix like 001_, 002_, etc.)
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Log each filename that would be applied
  console.log('Migrations to apply:');
  sqlFiles.forEach(file => {
    console.log('  -', file);
  });

  console.log(`\nTotal migrations: ${sqlFiles.length}`);
}

// Run the migration
migrate();

