const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');

/**
 * Parses a .env file and returns an object with the variables.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmed.substring(0, equalIndex);
      const value = trimmed.substring(equalIndex + 1);
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Resolves the database connection string from environment variables.
 */
function resolveConnectionString() {
  const envVars = parseEnvFile(envFile);
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Logs a simulated connection success message.
 */
function logConnectionSuccess(databaseUrl) {
  // Extract database name from connection string for display
  const dbName = databaseUrl.split('/').pop() || 'database';
  console.log(`Successfully connected to: ${dbName}`);
}

/**
 * Reads SQL files from the migrations directory and logs each filename
 * that would be applied, in order.
 */
function migrate() {
  // Resolve connection string from .env.test
  const databaseUrl = resolveConnectionString();
  logConnectionSuccess(databaseUrl);

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
    process.exit(1);
  }
